#include "emit_lua.hpp"

#include <llvm/ADT/StringExtras.h>
#include <llvm/ADT/StringSet.h>
#include <llvm/Support/FileSystem.h>
#include <llvm/Support/Path.h>
#include <llvm/Support/raw_ostream.h>

#include <algorithm>
#include <cstdint>
#include <map>
#include <optional>
#include <set>
#include <utility>

namespace dd {

    namespace {

        // First lines of every file: LuaLS reads `---@meta` files as declarations only.
        constexpr llvm::StringRef Header =
            "---@meta\n-- Generated by docs-digger from overlunky's sources: do not edit, regenerate.\n\n";

        // True for a Lua keyword, which cannot name a parameter or field.
        bool isKeyword(llvm::StringRef word) {
            static const llvm::StringSet<> keywords = {
                "and", "break", "do",  "else", "elseif", "end",    "false",  "for",  "function", "goto",  "if",
                "in",  "local", "nil", "not",  "or",     "repeat", "return", "then", "true",     "until", "while"};
            return keywords.contains(word);
        }

        // True for a Lua name: an identifier that is no keyword.
        bool isLuaName(llvm::StringRef text) {
            return !text.empty() && !llvm::isDigit(text.front()) &&
                llvm::all_of(text, [](char c) { return llvm::isAlnum(c) || c == '_'; }) && !isKeyword(text);
        }

        // What every writer needs.
        struct Context {
            // The settings of the run.
            const LuaFileSettings& settings;
            // Lua names of usertypes by C++ type as written and by canonical type, for base classes.
            std::map<std::string, std::string> classNames;
            // Globals and functions the prelude declares, which replace the generated ones.
            std::set<std::string> preludeNames;
            // The extraction written, for the events of enum-selected callbacks.
            const Extraction& extraction;
        };

        // The names a prelude declares at the start of a line: `name = ...` and `function name(...)`.
        std::set<std::string> declaredNames(llvm::StringRef prelude) {
            std::set<std::string> names;
            llvm::SmallVector<llvm::StringRef, 64> lines;
            prelude.split(lines, '\n');
            for (llvm::StringRef line : lines) {
                line.consume_front("function ");
                const llvm::StringRef name = line.take_while([](char c) { return llvm::isAlnum(c) || c == '_'; });
                const llvm::StringRef rest = line.drop_front(name.size());
                if (!name.empty() && (rest.starts_with(" =") || rest.starts_with("("))) {
                    names.insert(name.str());
                }
            }
            return names;
        }

        // One doc line: `<br/>` (HTML for the old Markdown pages) dropped, `(#anchor)` links made absolute; a leading
        // `@` is moved off so LuaLS reads no annotation.
        std::string docLine(llvm::StringRef line, const Context& context) {
            std::string text = llvm::join(llvm::split(line, "<br/>"), "");
            if (!context.settings.docUrl.empty()) {
                text = llvm::join(llvm::split(text, "](#"), "](" + context.settings.docUrl + "#");
            }
            return llvm::StringRef(text).ltrim().starts_with("@") ? " " + text : text;
        }

        // Appends `---<line>` for every doc line, indented by indent.
        void appendDoc(std::string& out, const std::vector<std::string>& lines, const Context& context,
                       llvm::StringRef indent = "") {
            for (const std::string& line : lines) {
                out += indent.str() + "---" + docLine(line, context) + "\n";
            }
        }

        // Doc lines joined into one line, for `---@field` descriptions.
        std::string inlineDoc(const std::vector<std::string>& lines, const Context& context) {
            std::vector<std::string> parts;
            for (const std::string& line : lines) {
                if (!llvm::StringRef(line).trim().empty()) {
                    parts.push_back(docLine(llvm::StringRef(line).trim(), context));
                }
            }
            return parts.empty() ? std::string() : " " + llvm::join(parts, " ");
        }

        // The Lua type of a type, `any` when it has no name.
        std::string typeName(const TypeInfo& type) { return type.lua.empty() ? "any" : type.lua; }

        // True when the files use the classic EmmyLua dialect.
        bool isEmmy(const Context& context) { return context.settings.style == LuaStyle::EmmyLua; }

        // Index of the `]` that closes the `[` at open.
        std::size_t closingBracket(llvm::StringRef text, std::size_t open) {
            int depth = 0;
            for (std::size_t i = open; i < text.size(); ++i) {
                depth += text[i] == '[' ? 1 : (text[i] == ']' ? -1 : 0);
                if (depth == 0) {
                    return i;
                }
            }
            return text.size() - 1;
        }

        // At `,` or `)`: ends the type of an optional `fun` parameter with `|nil`; tracks the `(` depth.
        void closeParam(std::string& out, std::vector<bool>& nilPending, char c) {
            if ((c == ',' || c == ')') && nilPending.back()) {
                out += "|nil";
                nilPending.back() = false;
            }
            if (c == '(') {
                nilPending.push_back(false);
            }
            else if (c == ')' && nilPending.size() > 1) {
                nilPending.pop_back();
            }
        }

        // At `[`: an array suffix `[]` stays, a tuple `[A, B]` becomes `table`; returns the index of the last
        // character used.
        std::size_t emmyBracket(std::string& out, llvm::StringRef lua, std::size_t i) {
            if (lua.substr(i).starts_with("[]")) {
                out += "[]";
                return i + 1;
            }
            out += "table";
            return closingBracket(lua, i);
        }

        // At `?`: `T?` becomes `T|nil`; the `?` of an optional `fun` parameter (`b?: B`) moves behind its type.
        void emmyMark(std::string& out, llvm::StringRef lua, std::size_t i, std::vector<bool>& nilPending) {
            if (lua.substr(i).starts_with("?:")) {
                nilPending.back() = true;
            }
            else {
                out += "|nil";
            }
        }

        // A LuaLS type in classic EmmyLua: a tuple `[A, B]` becomes `table`, `T?` becomes `T|nil`, and an optional
        // `fun` parameter `b?: B` becomes `b: B|nil`.
        std::string emmyType(llvm::StringRef lua) {
            std::string out;
            std::vector<bool> nilPending{false};
            for (std::size_t i = 0; i < lua.size(); ++i) {
                if (lua[i] == '[') {
                    i = emmyBracket(out, lua, i);
                }
                else if (lua[i] == '?') {
                    emmyMark(out, lua, i, nilPending);
                }
                else {
                    closeParam(out, nilPending, lua[i]);
                    out += lua[i];
                }
            }
            return out;
        }

        // A type as the style writes it.
        std::string written(const Context& context, const std::string& lua) {
            return isEmmy(context) ? emmyType(lua) : lua;
        }

        // A description (starting with a space) as the style writes it: EmmyLua reads it after `@`.
        std::string described(const Context& context, const std::string& text) {
            return isEmmy(context) && !text.empty() ? " @" + text.substr(1) : text;
        }

        // `T?`, without doubling the mark.
        std::string orNil(const std::string& lua) { return lua.ends_with('?') ? lua : lua + "?"; }

        // The parameters Lua passes: hidden ones left out, and the object when a method receives it first.
        std::vector<const Param*> visibleParams(const std::vector<Param>& params, bool objectFirst) {
            std::vector<const Param*> visible;
            for (const Param& param : params) {
                if (param.type.hidden) {
                    continue;
                }
                if (objectFirst) {
                    objectFirst = false;
                    continue;
                }
                visible.push_back(&param);
            }
            return visible;
        }

        // The Lua parameters of sig.
        std::vector<const Param*> visibleParams(const FunctionSig& sig) {
            return visibleParams(sig.params, sig.self == SelfKind::FirstParam);
        }

        // Lua name of the index-th parameter: its C++ name (a keyword gets `_`), `p<n>` when unnamed, `...` for
        // variadic arguments.
        std::string paramName(const Param& param, std::size_t index) {
            if (param.type.kind == TypeKind::Variadic) {
                return "...";
            }
            if (param.name.empty()) {
                return "p" + std::to_string(index + 1);
            }
            return isKeyword(param.name) ? param.name + "_" : param.name;
        }

        std::string paramType(const Param& param);

        // `a: A, b?: B, ...: any`: the parameters inside a `fun(...)` type.
        std::string funParams(const std::vector<const Param*>& params) {
            std::vector<std::string> parts;
            parts.reserve(params.size());
            for (std::size_t i = 0; i < params.size(); ++i) {
                const std::string name = paramName(*params[i], i);
                const std::string mark = params[i]->omittable && name != "..." ? "?" : "";
                parts.push_back(name + mark + ": " + paramType(*params[i]));
            }
            return llvm::join(parts, ", ");
        }

        // `fun(a: A): R` for a callback whose signature is known; `function` when it is unresolved or chosen by an
        // enum value (the events).
        std::string callbackType(const CallbackSig& callback) {
            if (callback.origin == CallbackOrigin::Unresolved || !callback.selector.empty()) {
                return "function";
            }
            std::string text = "fun(" + funParams(visibleParams(callback.params, false)) + ")";
            std::vector<std::string> returns;
            returns.reserve(callback.returns.size());
            for (const TypeInfo& returned : callback.returns) {
                returns.push_back(callback.nilAllowed ? orNil(typeName(returned)) : typeName(returned));
            }
            return returns.empty() ? text : text + ": " + llvm::join(returns, ", ");
        }

        // The Lua type of a parameter: the callback signature it receives, else its type.
        std::string paramType(const Param& param) {
            if (param.type.kind == TypeKind::Variadic) {
                return "any";
            }
            if (!param.callback.empty()) {
                return callbackType(param.callback.front());
            }
            // An omittable parameter is marked on its name (`depth?`), which already allows nil.
            std::string type = typeName(param.type);
            if (param.omittable && type.ends_with('?')) {
                type.pop_back();
            }
            return type;
        }

        // `---@param` description: what a nil return of the callback the parameter receives means.
        std::string paramNote(const Param& param) {
            if (param.callback.empty() || param.callback.front().nilMeaning.empty()) {
                return {};
            }
            return " Returning nil: " + param.callback.front().nilMeaning + ".";
        }

        // `: A, B` after a `fun(...)`, or nothing for no returns.
        std::string funReturns(const std::vector<TypeInfo>& returns) {
            std::vector<std::string> names;
            names.reserve(returns.size());
            for (const TypeInfo& returned : returns) {
                names.push_back(typeName(returned));
            }
            return names.empty() ? std::string() : ": " + llvm::join(names, ", ");
        }

        // One `---@param` line; an omittable parameter is `name?` in LuaLS and `type|nil` in EmmyLua.
        void appendParam(std::string& out, const Param& param, std::size_t index, const Context& context) {
            const std::string name = paramName(param, index);
            std::string type = written(context, paramType(param));
            if (name == "..." && isEmmy(context)) {
                out += "---@vararg " + type + "\n";
                return;
            }
            std::string mark = param.omittable && name != "..." ? "?" : "";
            if (isEmmy(context) && !mark.empty()) {
                mark.clear();
                type += type.ends_with("|nil") ? "" : "|nil";
            }
            out += "---@param " + name + mark + " " + type + described(context, paramNote(param)) + "\n";
        }

        // The `---@param` and `---@return` lines of sig.
        void appendSignature(std::string& out, const FunctionSig& sig, const Context& context) {
            const std::vector<const Param*> params = visibleParams(sig);
            for (std::size_t i = 0; i < params.size(); ++i) {
                appendParam(out, *params[i], i, context);
            }
            for (const TypeInfo& returned : sig.returns) {
                out += "---@return " + written(context, typeName(returned)) + "\n";
            }
        }

        // `fun(self: Class, a: A): R` of a further overload; self only for overloads that receive the object.
        std::string overloadType(const FunctionSig& sig, const std::string& selfType) {
            std::string params = funParams(visibleParams(sig));
            if (!selfType.empty() && sig.self != SelfKind::None) {
                params = "self: " + selfType + (params.empty() ? "" : ", " + params);
            }
            return "fun(" + params + ")" + funReturns(sig.returns);
        }

        // The parameter list of the function statement.
        std::string paramList(const FunctionSig& sig) {
            const std::vector<const Param*> params = visibleParams(sig);
            std::vector<std::string> names;
            names.reserve(params.size());
            for (std::size_t i = 0; i < params.size(); ++i) {
                names.push_back(paramName(*params[i], i));
            }
            return llvm::join(names, ", ");
        }

        // A function statement to write.
        struct FunctionDecl {
            // Name as declared: `spawn`, `io.open_data`, `Entity:topmost`, `Vec2.new`.
            std::string name;
            // The class of a method, named in the `self` of further overloads; empty for plain functions.
            std::string selfType;
            // Doc lines.
            std::vector<std::string> doc;
            // `/// Deprecated`.
            bool deprecated = false;
            // Callable forms; the first is declared, the others become `---@overload`.
            std::vector<FunctionSig> overloads;
        };

        // The value of an event's key in its enum table as a LuaLS literal type (`12`); empty when it has no number.
        std::string enumLiteral(const Extraction& extraction, const Event& event) {
            const auto found = extraction.enums.find(event.table);
            if (found == extraction.enums.end()) {
                return {};
            }
            for (const auto& [valueKey, value] : found->second.values) {
                if (value.luaName == event.luaName && value.number) {
                    return std::to_string(*value.number);
                }
            }
            return {};
        }

        // The parameter that receives a callback chosen by an enum value, and the one that takes the value.
        struct EventParams {
            // Index of the callback parameter among the visible ones.
            std::size_t callback = 0;
            // Index of the parameter typed with the selecting enum.
            std::size_t selector = 0;
            // The callback's facts (selector and storage).
            const CallbackSig* sig = nullptr;
        };

        // Index of the parameter typed with the enum table named selector.
        std::optional<std::size_t> selectorIndex(const std::vector<const Param*>& params, const std::string& selector) {
            for (std::size_t i = 0; i < params.size(); ++i) {
                if (typeName(params[i]->type) == selector) {
                    return i;
                }
            }
            return std::nullopt;
        }

        // The event parameters of a signature, if it has a callback chosen by an enum parameter.
        std::optional<EventParams> eventParams(const std::vector<const Param*>& params) {
            for (std::size_t i = 0; i < params.size(); ++i) {
                const CallbackSig* callback = params[i]->callback.empty() ? nullptr : &params[i]->callback.front();
                if (callback == nullptr || callback->selector.empty()) {
                    continue;
                }
                if (const std::optional<std::size_t> selector = selectorIndex(params, callback->selector)) {
                    return EventParams{i, *selector, callback};
                }
            }
            return std::nullopt;
        }

        // The Lua types an event overload writes for the two event parameters.
        struct EventTypes {
            // The callback's `fun(...)` type for this event.
            std::string callback;
            // The event's value as a literal type.
            std::string literal;
        };

        // `fun(cb: <the event's callback>, event: 12): R`, one overload of an event registration.
        std::string eventOverload(const FunctionSig& sig, const std::vector<const Param*>& params,
                                  const EventParams& event, const EventTypes& types, const std::string& selfType) {
            std::vector<std::string> parts;
            if (!selfType.empty() && sig.self != SelfKind::None) {
                parts.push_back("self: " + selfType);
            }
            for (std::size_t i = 0; i < params.size(); ++i) {
                const std::string type = i == event.callback ? types.callback
                    : i == event.selector                    ? types.literal
                                                             : paramType(*params[i]);
                parts.push_back(paramName(*params[i], i) + ": " + type);
            }
            return "fun(" + llvm::join(parts, ", ") + ")" + funReturns(sig.returns);
        }

        // One `---@overload` per event of the storage the callback goes to: the callback typed for that event, the
        // selecting parameter as the event's literal value, by which LuaLS tells `ON.FRAME` from `ON.LEVEL`. LuaLS
        // only: classic EmmyLua has no literal types.
        void appendEventOverloads(std::string& out, const FunctionSig& sig, const std::string& selfType,
                                  const Context& context) {
            const std::vector<const Param*> params = visibleParams(sig);
            const std::optional<EventParams> found = eventParams(params);
            if (isEmmy(context) || !found) {
                return;
            }
            for (const auto& [key, event] : context.extraction.events) {
                const bool matches = event.table == found->sig->selector && event.storedIn == found->sig->storedIn &&
                    event.callback.origin != CallbackOrigin::Unresolved;
                const std::string literal = matches ? enumLiteral(context.extraction, event) : std::string();
                if (!literal.empty()) {
                    // Without the callback's returns: LuaLS (3.19) selects an overload by a function argument only
                    // when the `fun` type declares none; with one it falls back to the untyped signature.
                    CallbackSig arguments = event.callback;
                    arguments.returns.clear();
                    out += "---@overload " +
                        eventOverload(sig, params, *found, {callbackType(arguments), literal}, selfType) + "\n";
                }
            }
        }

        // Appends one documented function statement.
        void appendFunction(std::string& out, const FunctionDecl& decl, const Context& context) {
            appendDoc(out, decl.doc, context);
            if (decl.deprecated) {
                out += "---@deprecated\n";
            }
            if (decl.overloads.empty()) {
                out += "function " + decl.name + "(...) end\n\n";
                return;
            }
            appendSignature(out, decl.overloads.front(), context);
            for (const FunctionSig& other : llvm::drop_begin(decl.overloads)) {
                out += "---@overload " + written(context, overloadType(other, decl.selfType)) + "\n";
            }
            for (const FunctionSig& sig : decl.overloads) {
                appendEventOverloads(out, sig, decl.selfType, context);
            }
            out += "function " + decl.name + "(" + paramList(decl.overloads.front()) + ") end\n\n";
        }

        // Doc lines of a binding, or of its first C++ target when the binding has none.
        std::vector<std::string> docOf(const Doc& doc, const std::vector<FunctionSig>& overloads) {
            if (!doc.lines.empty() || overloads.empty()) {
                return doc.lines;
            }
            return overloads.front().doc.lines;
        }

        // `io.open_data` from root, owner keys and name; empty when a part is no Lua name (`TYPE_MAP[...]`).
        std::string qualifiedName(const Function& function) {
            std::vector<std::string> parts;
            if (!function.root.empty()) {
                parts.push_back(function.root);
            }
            parts.insert(parts.end(), function.owner.begin(), function.owner.end());
            parts.push_back(function.luaName);
            return llvm::all_of(parts, [](const std::string& part) { return isLuaName(part); }) ? llvm::join(parts, ".")
                                                                                                : std::string();
        }

        // Documented functions by group, each sorted by name; a name bound twice keeps its first binding.
        std::map<std::string, std::map<std::string, const Function*>> functionsByGroup(const Extraction& extraction,
                                                                                       const Context& context) {
            std::map<std::string, std::map<std::string, const Function*>> groups;
            for (const auto& [key, function] : extraction.functions) {
                const std::string name = qualifiedName(function);
                if (!function.doc.nodoc && !name.empty() && !context.preludeNames.contains(name)) {
                    groups[function.group].try_emplace(name, &function);
                }
            }
            return groups;
        }

        // One chunk per function group (`-- ## Spawn functions`).
        void addFunctionChunks(std::vector<std::string>& chunks, const Extraction& extraction, const Context& context) {
            for (const auto& [group, functions] : functionsByGroup(extraction, context)) {
                std::string chunk = "-- ## " + group + "\n\n";
                for (const auto& [name, function] : functions) {
                    appendFunction(chunk,
                                   {name,
                                    {},
                                    docOf(function->doc, function->overloads),
                                    function->doc.deprecated,
                                    function->overloads},
                                   context);
                }
                chunks.push_back(std::move(chunk));
            }
        }

        // `---@type T` and `name = nil`, with docs.
        void appendGlobal(std::string& out, const std::string& name, const std::string& type, const Doc& doc,
                          const Context& context) {
            appendDoc(out, doc.lines, context);
            out += "---@type " + written(context, type) + "\n" + name + " = nil\n\n";
        }

        // `Util = {}` for the tables that hold written functions (`Util.spawn_helper`) and are declared nowhere else:
        // no Lua standard library, usertype, enum or prelude global.
        std::string namespaceTables(const Extraction& extraction, const Context& context) {
            static const std::set<std::string> standard = {"coroutine", "debug",  "io",    "math", "os",
                                                           "package",   "string", "table", "utf8"};
            std::set<std::string> tables;
            for (const auto& [group, functions] : functionsByGroup(extraction, context)) {
                for (const auto& [name, function] : functions) {
                    const llvm::StringRef table = llvm::StringRef(name).split('.').first;
                    if (table.size() != name.size()) {
                        tables.insert(table.str());
                    }
                }
            }
            std::string out;
            for (const std::string& table : tables) {
                const bool usertype =
                    llvm::any_of(context.classNames, [&table](const auto& entry) { return entry.second == table; });
                const bool declared = standard.contains(table) || extraction.enums.contains(table) || usertype ||
                    context.preludeNames.contains(table);
                out += declared ? "" : table + " = {}\n\n";
            }
            return out;
        }

        // `-- ## <title>` and body, or nothing when body is empty.
        std::string section(const std::string& title, const std::string& body) {
            return body.empty() ? std::string() : "-- ## " + title + "\n\n" + body;
        }

        // A global variable as the values bound to its name give it: docs from the documented binding, the type from
        // a compiled one (a documented commented-out binding stands next to the real one for `players`).
        std::pair<Doc, std::string> globalVariable(const Extraction& extraction, const std::string& name) {
            std::pair<Doc, std::string> result;
            auto& [doc, type] = result;
            for (const auto& [key, value] : extraction.values) {
                if (value.luaName != name || !key.owner.empty() || !value.root.empty()) {
                    continue;
                }
                if (doc.lines.empty()) {
                    doc = value.doc;
                }
                if (type.empty() || (!value.docOnly && type == "any")) {
                    type = typeName(value.type);
                }
            }
            return result;
        }

        // The global variables (and the tables of namespaced functions), unless the prelude declares them.
        std::string globalsChunk(const Extraction& extraction, const Context& context) {
            std::string body = namespaceTables(extraction, context);
            for (const std::string& name : extraction.globalVariables) {
                if (!context.preludeNames.contains(name)) {
                    const auto [doc, type] = globalVariable(extraction, name);
                    appendGlobal(body, name, type, doc, context);
                }
            }
            return section("Global variables", body);
        }

        // The documented globals that scripts define (`on_frame`), once per name.
        std::string scriptCallbacksChunk(const Extraction& extraction, const Context& context) {
            std::string body;
            std::set<std::string> seen;
            for (const auto& [key, callback] : extraction.scriptCallbacks) {
                if (!callback.doc.nodoc && seen.insert(callback.luaName).second) {
                    appendGlobal(body, callback.luaName, typeName(callback.type), callback.doc, context);
                }
            }
            return section("Script callbacks: globals the script defines and the game calls", body);
        }

        // `---@alias` lines of the aliases that are not enum tables (those get theirs with the table).
        std::string aliasesChunk(const Extraction& extraction, const Context& context) {
            std::string body;
            for (const auto& [name, alias] : extraction.aliases) {
                if (!extraction.enums.contains(name) && !alias.doc.nodoc) {
                    appendDoc(body, alias.doc.lines, context);
                    body += "---@alias " + name + " " + written(context, typeName(alias.type)) + "\n";
                }
            }
            return section("Aliases", body.empty() ? body : body + "\n");
        }

        // A comment listing the Lua standard libraries the game opens, per opening function.
        std::string librariesChunk(const Extraction& extraction) {
            std::string body;
            for (const auto& [loc, call] : extraction.libraries) {
                body += "-- " + call.function + ": " + llvm::join(call.names, ", ") + "\n";
            }
            return section("Lua libraries", body);
        }

        // The members Lua sees, by name: a key bound twice keeps its last binding (sol2 keeps the last). NoDoc members
        // and keys that are no Lua names are left out; meta functions are kept for `---@operator`.
        std::map<std::string, const Member*> visibleMembers(const Usertype& usertype) {
            std::map<std::string, const Member*> members;
            for (const auto& [key, member] : usertype.members) {
                members[member.luaName] = &member;
            }
            std::erase_if(members, [](const auto& entry) {
                const Member& member = *entry.second;
                return member.doc.nodoc || (!member.meta && !isLuaName(member.luaName));
            });
            return members;
        }

        // LuaLS operator names of sol::meta_function keys; other meta functions have no LuaLS annotation.
        llvm::StringRef operatorName(llvm::StringRef metaFunction) {
            static const std::map<llvm::StringRef, llvm::StringRef> operators = {
                {"addition", "add"}, {"subtraction", "sub"},    {"multiplication", "mul"},   {"division", "div"},
                {"modulus", "mod"},  {"unary_minus", "unm"},    {"concatenation", "concat"}, {"length", "len"},
                {"power_of", "pow"}, {"floor_division", "idiv"}};
            const auto found = operators.find(metaFunction);
            return found == operators.end() ? llvm::StringRef() : found->second;
        }

        // `---@operator add(Vec2): Vec2` for an operator meta function.
        void appendOperator(std::string& out, const Member& member, const std::string& className) {
            const llvm::StringRef name = operatorName(member.luaName);
            if (name.empty() || member.overloads.empty()) {
                return;
            }
            const FunctionSig& sig = member.overloads.front();
            const std::vector<const Param*> params = visibleParams(sig);
            const std::string operand = params.empty() ? std::string() : "(" + paramType(*params.front()) + ")";
            const std::string result = sig.returns.empty() ? className : typeName(sig.returns.front());
            out += "---@operator " + name.str() + operand + ": " + result + "\n";
        }

        // `---@field [integer] Player` for a `sol::meta_function::index` function taking one key.
        void appendIndexField(std::string& out, const Member& member) {
            if (member.luaName != "index" || member.overloads.empty()) {
                return;
            }
            const FunctionSig& sig = member.overloads.front();
            const std::vector<const Param*> params = visibleParams(sig);
            if (params.size() == 1 && !sig.returns.empty()) {
                std::string value = typeName(sig.returns.front());
                if (value.ends_with('?')) {
                    value.pop_back();
                }
                out += "---@field [" + paramType(*params.front()) + "] " + value + "\n";
            }
        }

        // `---@field name type doc` of a field, property or value member.
        void appendField(std::string& out, const Member& member, const Context& context) {
            const std::vector<std::string>& doc = member.doc.lines.empty() ? member.declDoc.lines : member.doc.lines;
            out += "---@field " + member.luaName + " " + written(context, typeName(member.type)) +
                described(context, inlineDoc(doc, context)) + "\n";
        }

        // `Class:method` for methods that receive the object, `Class.function` for the others.
        FunctionDecl methodDecl(const Usertype& usertype, const Member& member) {
            const bool method = !member.overloads.empty() && member.overloads.front().self != SelfKind::None;
            std::vector<std::string> doc = member.doc.lines;
            if (doc.empty()) {
                doc = docOf(member.declDoc, member.overloads);
            }
            return {usertype.luaName + (method ? ":" : ".") + member.luaName, usertype.luaName, std::move(doc),
                    member.doc.deprecated, member.overloads};
        }

        // `Class.new` with the constructors, each returning the class.
        FunctionDecl constructorDecl(const Usertype& usertype) {
            FunctionDecl decl{usertype.luaName + ".new", {}, {}, false, usertype.constructors};
            TypeInfo created;
            created.lua = usertype.luaName;
            for (FunctionSig& sig : decl.overloads) {
                sig.returns = {created};
            }
            decl.doc = decl.overloads.front().doc.lines;
            return decl;
        }

        // ` : Base1, Base2` from the C++ bases that are usertypes.
        std::string basesOf(const Usertype& usertype, const Context& context) {
            std::vector<std::string> names;
            for (const std::string& base : usertype.bases) {
                if (const auto found = context.classNames.find(base); found != context.classNames.end()) {
                    names.push_back(found->second);
                }
            }
            return names.empty() ? std::string() : " : " + llvm::join(names, ", ");
        }

        // The class line of a NoDoc usertype, with its index field: enough for references to resolve.
        // Its members inherit the NoDoc of the statement, so all of them are looked at.
        std::string stubChunk(std::string chunk, const Usertype& usertype, const Context& context) {
            for (const auto& [key, member] : usertype.members) {
                if (member.meta && !isEmmy(context)) {
                    appendIndexField(chunk, member);
                }
            }
            return chunk + "\n";
        }

        // The annotation lines of a class's members: operators and index fields (LuaLS only), fields.
        void appendMemberLines(std::string& chunk, const Usertype& usertype,
                               const std::map<std::string, const Member*>& members, const Context& context) {
            for (const auto& [name, member] : members) {
                if (member->meta && !isEmmy(context)) {
                    appendOperator(chunk, *member, usertype.luaName);
                    appendIndexField(chunk, *member);
                }
                else if (member->kind != MemberKind::Method) {
                    appendField(chunk, *member, context);
                }
            }
        }

        // The class block of a usertype: fields and operators, the global table, then constructors and methods.
        std::string usertypeChunk(const Usertype& usertype, const Context& context) {
            std::string chunk;
            appendDoc(chunk, usertype.doc.lines.empty() ? usertype.declDoc.lines : usertype.doc.lines, context);
            chunk += "---@class " + usertype.luaName + basesOf(usertype, context) + "\n";
            const std::map<std::string, const Member*> members = visibleMembers(usertype);
            if (usertype.doc.nodoc) {
                // Not documented, but documented members return it (`as_webgun`, `players`): the class only.
                return stubChunk(chunk, usertype, context);
            }
            appendMemberLines(chunk, usertype, members, context);
            chunk += usertype.luaName + " = {}\n\n";
            if (!usertype.constructors.empty()) {
                appendFunction(chunk, constructorDecl(usertype), context);
            }
            for (const auto& [name, member] : members) {
                if (!member->meta && member->kind == MemberKind::Method) {
                    appendFunction(chunk, methodDecl(usertype, *member), context);
                }
            }
            return chunk;
        }

        // A Lua string literal.
        std::string luaString(llvm::StringRef text) {
            std::string out = "\"";
            for (const char c : text) {
                if (c == '"' || c == '\\') {
                    out += '\\';
                }
                out += c == '\n' ? std::string("\\n") : std::string(1, c);
            }
            return out + "\"";
        }

        // How good a value is to write: one known in the code beats the runtime file, which beats a commented-out
        // example; a value with a literal beats one without.
        int valueRank(const EnumValue& value) {
            const int origin =
                value.origin == EnumValueOrigin::Static ? 2 : (value.origin == EnumValueOrigin::RuntimeFile ? 1 : 0);
            return origin * 2 + (value.number || value.string ? 1 : 0);
        }

        // The best value per key, keys that are empty (hints) left out.
        std::map<std::string, const EnumValue*> enumValues(const Enum& table) {
            std::map<std::string, const EnumValue*> values;
            for (const auto& [key, value] : table.values) {
                if (value.luaName.empty()) {
                    continue;
                }
                const EnumValue*& best = values[value.luaName];
                if (best == nullptr || valueRank(value) > valueRank(*best)) {
                    best = &value;
                }
            }
            return values;
        }

        // The type the enum's alias names: integer, string, or both.
        std::string enumType(const std::map<std::string, const EnumValue*>& values) {
            const bool strings =
                llvm::any_of(values, [](const auto& entry) { return entry.second->string.has_value(); });
            const bool numbers = llvm::any_of(values, [](const auto& entry) { return !entry.second->string; });
            return strings ? (numbers ? "integer|string" : "string") : "integer";
        }

        // `0x10, -- 1 << 4` or `0x6000, -- WATER | LAVA`: a bit flag in hex with its bits; decimal when negative (an
        // overflowed `1 << 31`, which the hex form would hide).
        std::string flagValueText(const EnumValue& value) {
            const long long number = value.number.value_or(0);
            std::string text =
                number <= 0 ? std::to_string(number) : "0x" + llvm::utohexstr(static_cast<std::uint64_t>(number));
            if (value.bit) {
                return text + ", -- 1 << " + std::to_string(*value.bit);
            }
            return value.combines.empty() ? text + "," : text + ", -- " + llvm::join(value.combines, " | ");
        }

        // The `value,` part of an enum line; a value known only as code text is nil with the text in a comment.
        std::string enumValueText(const EnumValue& value, bool flags) {
            if (value.number) {
                return flags ? flagValueText(value) : std::to_string(*value.number) + ",";
            }
            return value.string ? luaString(*value.string) + "," : "nil, -- " + value.text;
        }

        // One `KEY = value,` line of an enum table, with the value's docs.
        void appendEnumValue(std::string& out, const EnumValue& value, bool flags, const Context& context) {
            appendDoc(out, value.doc.lines, context, "    ");
            const std::string key = isLuaName(value.luaName) ? value.luaName : "[" + luaString(value.luaName) + "]";
            out += "    " + key + " = " + enumValueText(value, flags) + "\n";
        }

        // Where a value of a bit flag table goes: zero first, then by its bits as an unsigned number (a written
        // `1 << 31` by its bit, though its number overflowed).
        std::uint64_t flagOrder(const EnumValue& value) {
            return value.bit ? std::uint64_t{1} << static_cast<unsigned>(*value.bit)
                             : static_cast<std::uint64_t>(value.number.value_or(0));
        }

        // The values to write in order: by key, or by bit in a bit flag table.
        std::vector<const EnumValue*> orderedValues(const Enum& table,
                                                    const std::map<std::string, const EnumValue*>& values) {
            std::vector<const EnumValue*> ordered;
            ordered.reserve(values.size());
            for (const auto& [name, value] : values) {
                ordered.push_back(value);
            }
            if (table.flags) {
                std::ranges::stable_sort(ordered, {}, [](const EnumValue* value) { return flagOrder(*value); });
            }
            return ordered;
        }

        // An enum table: `---@alias NAME integer` (scripts pass plain numbers too, which `---@enum` would reject)
        // and the table with its values, whose literals let LuaLS tell `ON.FRAME` from `ON.LEVEL`.
        std::string enumChunk(const Enum& table, const Context& context) {
            const std::map<std::string, const EnumValue*> values = enumValues(table);
            std::string chunk;
            appendDoc(chunk, table.doc.lines, context);
            if (!table.doc.lines.empty() && !table.usage.empty()) {
                chunk += "---\n"; // a paragraph break: Markdown would join the docs and the usage text
            }
            appendDoc(chunk, table.usage, context);
            chunk += "---@alias " + table.luaName + " " + enumType(values) + "\n" + table.luaName + " = {\n";
            for (const EnumValue* value : orderedValues(table, values)) {
                appendEnumValue(chunk, *value, table.flags, context);
            }
            return chunk + "}\n\n";
        }

        // `spel2_types_2.lua` for base `spel2_types` and index 2; index 1 has no suffix.
        std::string fileName(llvm::StringRef base, int index) {
            return base.str() + (index == 1 ? "" : "_" + std::to_string(index)) + ".lua";
        }

        // Packs chunks into files of one kind, cutting only between chunks: a file that would grow past the limit
        // continues in the next one (a chunk larger than the limit gets a file of its own).
        void pack(std::vector<LuaFile>& files, llvm::StringRef base, const std::vector<std::string>& chunks,
                  std::size_t maxFileSize) {
            if (llvm::all_of(chunks, [](const std::string& chunk) { return chunk.empty(); })) {
                return;
            }
            int index = 1;
            std::string text = Header.str();
            for (const std::string& chunk : chunks) {
                if (chunk.empty()) {
                    continue;
                }
                if (text.size() > Header.size() && text.size() + chunk.size() > maxFileSize) {
                    files.push_back({fileName(base, index++), std::move(text)});
                    text = Header.str();
                }
                text += chunk;
            }
            files.push_back({fileName(base, index), std::move(text)});
        }

        // Usertype Lua names by C++ type as written and by canonical type.
        std::map<std::string, std::string> classNames(const Extraction& extraction) {
            std::map<std::string, std::string> names;
            for (const auto& [canonical, usertype] : extraction.usertypes) {
                if (!usertype.luaName.empty()) {
                    names.emplace(canonical, usertype.luaName);
                    names.emplace(usertype.cppType, usertype.luaName);
                }
            }
            return names;
        }

        // Chunks of spel2.lua: prelude, global variables, script callbacks, functions by group, aliases, libraries.
        std::vector<std::string> globalChunks(const Extraction& extraction, const Context& context) {
            std::vector<std::string> chunks;
            if (!context.settings.prelude.empty()) {
                chunks.push_back(context.settings.prelude + "\n");
            }
            chunks.push_back(globalsChunk(extraction, context));
            chunks.push_back(scriptCallbacksChunk(extraction, context));
            addFunctionChunks(chunks, extraction, context);
            chunks.push_back(aliasesChunk(extraction, context));
            chunks.push_back(librariesChunk(extraction));
            return chunks;
        }

        // One chunk per usertype, by Lua name (NoDoc ones as class stubs).
        std::vector<std::string> usertypeChunks(const Extraction& extraction, const Context& context) {
            std::map<std::string, const Usertype*> byName;
            for (const auto& [key, usertype] : extraction.usertypes) {
                if (!usertype.luaName.empty()) {
                    byName.try_emplace(usertype.luaName, &usertype);
                }
            }
            std::vector<std::string> chunks;
            chunks.reserve(byName.size());
            for (const auto& [name, usertype] : byName) {
                chunks.push_back(usertypeChunk(*usertype, context));
            }
            return chunks;
        }

        // One chunk per documented enum, by name.
        std::vector<std::string> enumChunks(const Extraction& extraction, const Context& context) {
            std::vector<std::string> chunks;
            for (const auto& [name, table] : extraction.enums) {
                if (!table.doc.nodoc) {
                    chunks.push_back(enumChunk(table, context));
                }
            }
            return chunks;
        }

        // Removes the `spel2*.lua` files of an earlier run (it may have cut the files differently).
        llvm::Error removeLuaFiles(const std::string& directory) {
            std::error_code error;
            for (llvm::sys::fs::directory_iterator it(directory, error), end; it != end && !error;
                 it.increment(error)) {
                const llvm::StringRef name = llvm::sys::path::filename(it->path());
                if (!name.starts_with("spel2") || !name.ends_with(".lua")) {
                    continue;
                }
                if (const std::error_code removed = llvm::sys::fs::remove(it->path())) {
                    return llvm::createStringError(removed, "cannot remove " + it->path());
                }
            }
            return llvm::Error::success();
        }

        // Writes one file with `\n` line ends.
        llvm::Error writeLuaFile(const LuaFile& file, const std::string& directory) {
            llvm::SmallString<256> path(directory);
            llvm::sys::path::append(path, file.name);
            std::error_code error;
            llvm::raw_fd_ostream out(path, error, llvm::sys::fs::OF_None);
            if (error) {
                return llvm::createStringError(error, "cannot write " + path.str().str());
            }
            out << file.text;
            return llvm::Error::success();
        }

    } // namespace

    std::vector<LuaFile> luaFiles(const Extraction& extraction, const LuaFileSettings& settings) {
        const Context context{settings, classNames(extraction), declaredNames(settings.prelude), extraction};
        std::vector<LuaFile> files;
        pack(files, "spel2", globalChunks(extraction, context), settings.maxFileSize);
        pack(files, "spel2_types", usertypeChunks(extraction, context), settings.maxFileSize);
        pack(files, "spel2_enums", enumChunks(extraction, context), settings.maxFileSize);
        return files;
    }

    llvm::Error writeLuaFiles(const std::vector<LuaFile>& files, const std::string& directory) {
        if (const std::error_code error = llvm::sys::fs::create_directories(directory)) {
            return llvm::createStringError(error, "cannot create " + directory);
        }
        if (llvm::Error error = removeLuaFiles(directory)) {
            return error;
        }
        for (const LuaFile& file : files) {
            if (llvm::Error error = writeLuaFile(file, directory)) {
                return error;
            }
        }
        return llvm::Error::success();
    }

} // namespace dd
